const DOMAIN = 'nutrition';       // или 'wellness'
const DATE_FIELD = 'Date';        // day_sum: 'Date'; Daily_Trends: 'Дата'

const windows = $('Define Month Windows').first().json;
const items = $input.all().map(i => i.json);

const tagged = [];
items.forEach(r => {
  const dateVal = (r[DATE_FIELD] || '').toString().slice(0, 7);
  if (dateVal === windows.current_month) {
    tagged.push({ ...r, __period: 'current', domain: DOMAIN });
  } else if (dateVal === windows.previous_month) {
    tagged.push({ ...r, __period: 'previous', domain: DOMAIN });
  }
});

return tagged.map(r => ({ json: r }));

