  }
});

return tagged.map(r => ({ json: r }));

function toNumber(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace(',', '.').replace('%',''));
  return isNaN(n) ? null : n;
}

const items = $input.all().map(i => i.json).filter(r => r.__period === 'current');
if (items.length === 0) return [{ json: { warning: 'Нет строк за текущий месяц' } }];

const exclude = ['User_ID', 'Date', 'Дата', '__period', 'domain', 'row_number'];
const fieldSet = new Set();
items.forEach(r => Object.keys(r).forEach(k => { if (!exclude.includes(k)) fieldSet.add(k); }));

const sums = {}, counts = {};
fieldSet.forEach(f => { sums[f] = 0; counts[f] = 0; });

items.forEach(r => {
  fieldSet.forEach(f => {
    const v = toNumber(r[f]);
    if (v !== null) { sums[f] += v; counts[f] += 1; }
  });
});

const monthKey = $('Define Month Windows').first().json.current_month;
const totalRow = { User_ID: 'Влад Васюк', Date: monthKey, 'Способ подсчета': 'total' };
const avgRow = { User_ID: 'Влад Васюк', Date: monthKey, 'Способ подсчета': 'average' };

fieldSet.forEach(f => {
  totalRow[f] = Math.round(sums[f] * 100) / 100;
  avgRow[f] = counts[f] > 0 ? Math.round((sums[f] / counts[f]) * 100) / 100 : null;
});

return [{ json: totalRow }, { json: avgRow }];

