  const prevVals = prevRows.map(r => toNumber(r[m])).filter(v => v !== null);
  if (curVals.length < MIN_N || prevVals.length < MIN_N) return;

  const cur = meanStd(curVals);
  const prev = meanStd(prevVals);
  const se = Math.sqrt((cur.std ** 2) / cur.n + (prev.std ** 2) / prev.n);
  if (se === 0 || isNaN(se)) return;
  const z = (cur.mean - prev.mean) / se;
  const absZ = Math.abs(z);

  let severity = null;
  if (absZ >= Z_STRONG) severity = 'strong';
  else if (absZ >= Z_MODERATE) severity = 'moderate';
  if (!severity) return;

  const direction = DIRECTION[m] || 'neutral';
  let interpretation = 'изменение';
  if (direction === 'higher_better') interpretation = z > 0 ? 'улучшение' : 'ухудшение';
  if (direction === 'lower_better') interpretation = z > 0 ? 'ухудшение' : 'улучшение';

  results.push({
    date_computed: DateTime.now().toISODate(),
    domain: DOMAIN,
    metric: m,
    prev_month_mean: Math.round(prev.mean * 100) / 100,
    this_month_mean: Math.round(cur.mean * 100) / 100,
    z: Math.round(z * 100) / 100,
    n_current: cur.n, n_previous: prev.n,
    severity, direction, interpretation
  });
});

return results.length ? results.map(r => ({ json: r })) : [{ json: { domain: DOMAIN, info: 'Значимых сдвигов нет' } }];

