={{ (() => {
  const items = $input.all().map(i => i.json).filter(r => r.severity);
  const strong = items.filter(r => r.severity === 'strong');
  const top = (strong.length ? strong : items).slice(0, 6);

  const lines = top.map(r => {
    const arrow = r.interpretation === 'улучшение' ? '📈' : r.interpretation === 'ухудшение' ? '📉' : '↔️';
    return `${arrow} ${r.metric} (${r.domain}): ${r.prev_month_mean} → ${r.this_month_mean}`;
  });

  return `📊 Месячный тренд за ${items[0]?.period_month || 'этот месяц'}\n` +
         `Сдвигов: ${items.length} (сильных: ${strong.length})\n\n` +
         lines.join('\n') +
         `\n\nПолный разбор — в Gemini Spark.`;
})() }}

