  if (direction === 'lower_better') interpretation = z > 0 ? 'ухудшение' : 'улучшение';

  results.push({
    date_computed: DateTime.now().toISODate(),
    domain: DOMAIN,
    metric: m,
    prev_month_mean: Math.round(prev.mean * 100) / 100,
    this_month_mean: Math.round(cur.mean * 100) / 100,
    z: Math.round(z * 100) / 100,
    n_current: cur.n, n_previous: prev.n,
    severity, direction, interpretation
  });
});

